arguments.command:
python3 - <<'EOF'
import json,re,hashlib,pathlib
files=['runner.py','qat_cache_mask_data.py','experiment_logging.py','shared_runtime.py','attention_observer.py','inspect_same_token.py','vendor/qat_kv/turboquant_attn_hook.py','vendor/qat_kv/turboquant_fake_quant.py','vendor/qat_kv/oscar_windowed_attn.py']
cur={p:hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest() for p in files}
for p in sorted(pathlib.Path('evidence/history_logs').glob('segment-*.stdout.log')):
    text=p.read_text()
    start=text.find('{\n  "status"')
    if start<0: continue
    end=text.rfind('\n}')+2
    try: obj=json.loads(text[start:end])
    except Exception as e: print(p,'parse fail',e); continue
    man=obj.get('as_used_source_manifest',{})
    inv={}
    for k,v in man.items(): inv.setdefault(v,[]).append(k)
    print('==',p.name,obj.get('status'),'step',obj.get('completed_global_step'),'manifest',len(man))
    for f,h in cur.items():
        print('  ',f, 'MATCH' if h in inv else 'no', inv.get(h,[])[:2])
EOF

